import{z as o,x as c,o as E,c as n,q as i,j as p,D as t,d as e,s as d,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const y=JSON.parse('{"title":"dm-crypt","description":"","frontmatter":{"title":"dm-crypt","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dm-crypt.md","filePath":"cs/dm-crypt.md","lastUpdated":1791413859000}'),m={name:"cs/dm-crypt.md"};function B(A,a,h,S,u,C){const s=c("Mermaid");return E(),n("div",null,[a[2]||(a[2]=i('<h1 id="dm-crypt" tabindex="-1">dm-crypt <a class="header-anchor" href="#dm-crypt" aria-label="Permalink to &quot;dm-crypt&quot;">​</a></h1><div class="epigraph"><p>dm-crypt 作为 device mapper 目标，对每个扇区加解密：上方面向明文块设备，下面是密文盘，密钥在内核密钥环。</p><footer>—— 据 Linux dm-crypt / cryptsetup 文档；Fruhwirth 对 LUKS 盘格式的说明</footer></div><p><a href="/cs/raid-levels-write-hole">上一课</a>的阵列仍是明文。<a href="/cs/device-mapper-lvm">dm</a> 的表可以插入 crypt 目标。缺口是 <strong>块层加密</strong>：XTS 等模式、LUKS 头、与 FS 校验的分工——不是 TLS，不是量化栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>丢盘等于泄露文件。FS 加密（fscrypt）按文件；dm-crypt 按设备，交换分区、整盘、LVM 下都能包。LUKS：口令派生密钥，槽可多用户。I/O：bio 明文进 crypt，CPU 或 AES-NI 处理后 remap 到下层。缺口：扇区 tweak 防止两处明文相同密文相同；TRIM 是否泄露空闲图（后课 discard）；对齐与 <a href="/cs/direct-io">O_DIRECT</a>。</p><p><span class="marginnote">术语翻译：tweak 可以想成「给每个扇区配一页不同的密码本」。同一份明文写在 100 号扇区和 200 号扇区，因页码不同，密文完全不同——攻击者看不出「这两块存的东西一样」。XTS 模式里这一页页码通常就是扇区号本身。</span></p><p><span class="marginnote">认证加密（integrity + crypt）另有 dm-integrity 叠层，抗重放与篡改，性能税更高。本课先钉保密性路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>cryptsetup luksOpen</code>：读 LUKS 头，把密钥装进 dm 表。之后 <code>/dev/mapper/name</code> 像普通盘，可再 LVM 或直接 mkfs。对照 <a href="/cs/xattr-acl">xattr</a>：文件级策略看不见整盘交换。对照 NFS：加密的是本地块，不是 RPC。CPU 占用可 cgroup，但对象仍是 bio。</p><p><span class="marginnote">直觉类比：LUKS 像酒店前台——你的口令开的是前台抽屉（密钥槽），抽屉里放真正的盘密钥；盘密钥才去开房间（数据）。所以换口令只需改抽屉，几毫秒完成，不必把几百 GB 数据重新加密一遍。</span></p>',10)),(E(),p(l,null,{default:t(()=>[d(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20CR%5B%22dm-crypt%22%5D%0A%20%20CR%20--%3E%20AES%5B%22%E6%8C%89%E6%89%87%E5%8C%BA%E5%8A%A0%E8%A7%A3%E5%AF%86%22%5D%0A%20%20AES%20--%3E%20DISK%5B%22%E4%B8%8B%E5%B1%82%E5%9D%97%E8%AE%BE%E5%A4%87%22%5D%0A%20%20KEY%5B%22LUKS%20%E5%AF%86%E9%92%A5%E6%A7%BD%22%5D%20--%3E%20CR%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("dm-crypt 把「落盘不可读」收成块层策略，FS 无需改布局。它不隐藏块号与大小模式——侧信道仍在。与 "),r("a",{href:"/cs/fs-checksum-scrub"},"COW 校验"),e("：校验宜在明文侧（FS）或另做认证层；只加密不认证会被替换扇区。不要把本课写成密码学课程重开。")],-1)),(E(),p(l,null,{default:t(()=>[d(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%8A%E5%B1%82%E5%86%99%E6%89%87%E5%8C%BA%EF%BC%88%E6%98%8E%E6%96%87%EF%BC%89%22%5D%20--%3E%20T1%5B%22%E4%BB%A5%E6%89%87%E5%8C%BA%E5%8F%B7%E7%AE%97%20tweak%22%5D%0A%20%20T1%20--%3E%20E%5B%22%E6%98%8E%E6%96%87%20XOR%20tweak%20%E5%90%8E%20AES%20%E5%8A%A0%E5%AF%86%EF%BC%8C%E5%86%8D%20XOR%20%E5%9B%9E%20tweak%22%5D%0A%20%20E%20--%3E%20C%5B%22%E5%AF%86%E6%96%87%E5%86%99%E8%BF%9B%E5%90%8C%E4%B8%80%E6%89%87%E5%8C%BA%22%5D%0A%20%20R%5B%22%E4%B8%8B%E5%B1%82%E8%AF%BB%E6%89%87%E5%8C%BA%EF%BC%88%E5%AF%86%E6%96%87%EF%BC%89%22%5D%20--%3E%20T2%5B%22%E7%94%A8%E5%90%8C%E4%B8%80%E6%89%87%E5%8C%BA%E5%8F%B7%E7%AE%97%20tweak%22%5D%0A%20%20T2%20--%3E%20D%5B%22%E5%AF%86%E6%96%87%20XOR%20tweak%20%E5%90%8E%20AES%20%E8%A7%A3%E5%AF%86%EF%BC%8C%E5%86%8D%20XOR%20%E5%9B%9E%20tweak%22%5D%0A%20%20D%20--%3E%20P%5B%22%E6%98%8E%E6%96%87%E4%BA%A4%E8%BF%98%E4%B8%8A%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：以为加密就能发现数据被篡改。实际上攻击者可以把两个密文扇区对调，解密照样「成功」，只是内容换了位置——盘上没有任何报错。要发现调包得另配校验（dm-integrity 或文件系统校验和）：加密管偷看，校验管调包。</span></p><p>启动：initramfs 里解锁根盘，后课 pivot 再遇。</p><p>实现上：XTS 的 tweak 通常是扇区号，克隆盘若扇区号相同会暴露模式。header 在 LUKS 里是明文的盐与算法，保护的是密钥槽而不是「这个盘存在」。 读法上只引用<a href="/cs/raid-levels-write-hole">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>dm-crypt</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TPM 解封的全部 PCR 策略——<a href="/cs/tpm-measured-boot">TPM</a> 在安全课序。不保证 SSD 的密文写放大故事写完。下一课从「逻辑大小」到「后端未写不占」：精简配置。</p><p>版本字段会变，课序钉的是机制对象「dm-crypt」，不是某一主线内核的结构体名。 后课默认：设备可透明加解密。逻辑卷超分配与按需分配块，下一课精简。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>dm-crypt 按扇区加密；LUKS 管密钥槽。</li><li>它不替代 FS 校验与完整性目标。</li><li>精简配置是下一课。</li><li>出处：dm-crypt；LUKS；Linux crypto API 概述。</li></ul>',10))])}const T=o(m,[["render",B]]);export{y as __pageData,T as default};
